<template>
  <div>
    <el-card class="top-card">
      <template #header>
        <div class="card-header">
            <input type="file" @change="handleFileChange" accept=".xlsx,.xls" />
        </div>
        <div>
          <!-- 添加表名输入框和转换按钮 -->
        <el-form :model="excelFrom" label-width="80px">
          <el-row>
            <el-col :span="6">
              <el-form-item label="表名"><el-input v-model="tableName" placeholder="请输入表名"></el-input></el-form-item>
            </el-col>
            <el-col :span="6">
            </el-col>
            <el-col :span="12" class="buttonList">
              <el-button type="primary" @click="clearJsonData">清空数据</el-button>
              <!-- 添加复制按钮 -->
              <el-button type="primary" @click="copyJsonToClipboard" :disabled="!jsonData">复制 JSON 数据</el-button>
              <el-button type="primary" @click="convertToInsertSql" :disabled="!jsonData || !tableName">转换为 SQL 语句</el-button>
            </el-col>
          </el-row>
        </el-form> 
        </div>
      </template>
    </el-card>

    <el-card class="content-card">
        <pre v-if="jsonData">{{ jsonData }}</pre>
    </el-card>
    
   
    <el-card class="bottom-card">
        <!-- 添加表格来显示 Excel 数据 -->
        <el-table :data="jsonData" v-if="jsonData && jsonData.length > 0">
        <el-table-column
            v-for="(key, index) in Object.keys(jsonData[0])"
            :key="index"
            :prop="key"
            :label="key"
        ></el-table-column>
        </el-table>
    </el-card>
    
  </div>
</template>

<script>
import * as XLSX from 'xlsx';

export default {
  data() {
    return {
      jsonData: null,
      tableName: '',
      insertSql: '',
      excelFrom: {
        tableName: '', // 表名
      }
    };
  },
  methods: {
    handleFileChange(event) {
      const file = event.target.files[0];
      if (file) {
        const reader = new FileReader();

        reader.onload = (e) => {
          const data = new Uint8Array(e.target.result);
          console.log(data);
          // Check if XLSX is defined
          if (XLSX) {
            console.log('XLSX:', XLSX);
            const workbook = XLSX.read(data, { type: 'array' });
            const firstSheetName = workbook.SheetNames[0];
            const worksheet = workbook.Sheets[firstSheetName];
            this.jsonData = XLSX.utils.sheet_to_json(worksheet);
          } else {
            console.error('XLSX library is not imported correctly.');
          }
        };
        reader.readAsArrayBuffer(file);
      }
    },
    clearJsonData() {
      this.jsonData = null;
      this.tableName = '';
      this.insertSql = '';
    },
    // 新增复制 JSON 数据到剪贴板的方法
    async copyJsonToClipboard() {
      if (this.jsonData) {
        try {
          const jsonString = JSON.stringify(this.jsonData, null, 2);
          await navigator.clipboard.writeText(jsonString);
          console.log('JSON 数据已复制到剪贴板');
        } catch (error) {
          console.error('复制 JSON 数据到剪贴板时出错:', error);
        }
      }
    },
    // 新增将 JSON 数据转换为 SQL INSERT 语句的方法
    convertToInsertSql() {
      if (this.jsonData && this.tableName) {
        const columns = Object.keys(this.jsonData[0]);
        const columnString = columns.map(col => `\`${col}\``).join(', ');
        const values = this.jsonData.map(item => {
          const rowValues = columns.map(col => {
            const value = item[col];
            if (typeof value === 'string') {
              return `'${value.replace(/'/g, "\\'")}'`;
            }
            return value;
          });
          return `(${rowValues.join(', ')})`;
        });
        const valuesString = values.join(', ');
        this.jsonData = `INSERT INTO \`${this.tableName}\` (${columnString}) VALUES ${valuesString};`;
      }
    }
  }
};
</script>
<style scoped>
.top-card {
  margin-bottom: 20px;
}
.content-card {
  margin-bottom: 20px;
}
.buttonList {
  display: flex;
  justify-content: flex-end;
}
</style>